function profil(){var me=(S.pu||"toi")=="toi",name=me?"toi":S.pu,all=me?MY:L.filter(function(l){return l.u==name}),sellerListings=L.filter(function(l){return l.u==name}),seller=sellerListings[0],ls=S.pt=="Favoris"?L.filter(function(l){return FAVORITES.indexOf(l.id)>-1}):all,h=back(me?"home":"detail")+'<div class="card"><div class="row"><div class="av">'+(me?"T":esc(name.charAt(0).toUpperCase()))+'</div><div style="flex:1"><b>'+esc(me?"Toi":name)+'</b><p class="s">'+(me?"Ton profil":seller?'Note '+esc(seller.s)+' sur 5 · '+esc(seller.n)+' transactions':"Profil membre")+'</p></div><span class="b ok">Démo</span></div>'+(me?"":'<div class="row" style="margin-top:10px"><button onclick="toggleFollow(\''+esc(name)+'\')">'+(FOLLOWS.indexOf(name)>-1?"Ne plus suivre":"Suivre")+'</button><button onclick="openChat(\''+esc(name)+'\')">Écrire</button></div>')+'</div>'+profileSummary(name,me)+(me?'<div class="card"><h3>Compléter ton profil</h3><p class="s" style="margin-top:4px">Indique une ville ou un secteur (pas d’adresse précise) et les jeux que tu collectionnes, séparés par des virgules. Ces informations restent dans ce navigateur.</p><label class="s" style="display:block;margin-top:10px">Ville ou secteur<input id="profile-city" maxlength="80" value="'+esc(PROFILE.city)+'" placeholder="Ex. Lyon"></label><label class="s" style="display:block;margin-top:10px">Jeux TCG collectionnés<input id="profile-games" maxlength="200" value="'+esc(PROFILE.games)+'" placeholder="Ex. Pokémon, Magic, One Piece"></label><label class="s" style="display:block;margin-top:10px">À propos de toi<textarea id="profile-bio" maxlength="240" rows="3" placeholder="Tes préférences, ce que tu recherches…">'+esc(PROFILE.bio)+'</textarea></label><button class="p" style="margin-top:10px" onclick="saveProfile()">Enregistrer le profil</button></div>':'')+'<div class="tabs">'+(me?["Annonces","Favoris","Avis"]:["Annonces","Avis"]).map(function(t){return '<button class="tab'+(S.pt==t?' on':'')+'" onclick="go(\'profil\',{pu:\''+esc(S.pu)+'\',pt:\''+t+'\'})">'+t+'</button>'}).join("")+'</div>';
if(S.pt=="Avis"){var reviews=REVIEWS[S.pu]||[];return h+(reviews.length?reviews.map(function(r){return '<div class="card"><b>'+r.rating+' ★</b><p class="s">Avis de la démo · '+messageTime(r.time)+'</p></div>'}).join(""):'<div class="card"><p class="s">Aucun avis enregistré pour le moment.</p></div>')}
if(!ls.length)return h+'<div class="card"><p class="s">'+(S.pt=="Favoris"?"Tu n’as pas encore de favoris. Ajoute-en depuis une annonce.":"Aucune annonce à afficher.")+'</p></div>';
return h+'<div class="grid">'+ls.map(function(l){return tile(l,me?1:0)}).join("")+'</div>'}
function publier(){var games=G.map(function(g){return '<option value="'+esc(g)+'">'+esc(g)+'</option>'}).join(""),conditions=CARD_CONDITIONS.map(function(e){return '<option value="'+esc(e)+'">'+esc(e)+'</option>'}).join(""),defects=["Recto","Verso"].map(function(side){var sideDefects=CARD_DEFECTS.filter(function(defect){return defect.side==side}).map(function(defect){return '<label class="defect-option" for="publish-defect-'+esc(defect.id)+'"><input id="publish-defect-'+esc(defect.id)+'" type="checkbox" value="'+esc(defect.id)+'"><span>'+esc(defect.label)+'</span></label>'}).join("");return '<section class="defect-face"><h4 class="defect-face-title">'+side+' <span>'+(side=="Recto"?"Face avant":"Face arrière")+'</span></h4><div class="defect-options">'+sideDefects+'</div></section>'}).join(""),centering=CENTERING_QUALITIES.map(function(quality){return '<option value="'+esc(quality)+'">'+esc(quality)+'</option>'}).join("");
return back("home")+'<h2>Publier une annonce</h2><p class="s">Présente ta carte et indique si tu la vends, l’échanges ou la mets aux enchères.</p><div class="card"><label class="s" style="display:block">Nom de la carte<input id="publish-name" maxlength="100" placeholder="Ex. Mew ex"></label><label class="s" style="display:block;margin-top:10px">Jeu<select id="publish-game"><option value="">Choisir un jeu</option>'+games+'</select></label><label class="s" style="display:block;margin-top:10px">Je propose<select id="publish-type" onchange="toggleAuctionFields()"><option value="Vente">Vente</option><option value="Échange">Échange</option><option value="Enchère">Enchère</option></select></label><label class="s" style="display:block;margin-top:10px">État<select id="publish-condition">'+conditions+'</select></label><fieldset class="defect-fieldset"><legend>Défauts visibles (facultatif)</legend><p class="s defect-help">Coche uniquement les défauts présents sur chaque face de la carte.</p><div class="defect-faces">'+defects+'</div></fieldset><label class="s" style="display:block;margin-top:10px">Centrage estimé<select id="publish-centering"><option value="">Non renseigné</option>'+centering+'</select></label><p class="s" style="margin-top:5px">Choisis le niveau correspondant au centrage de la carte.</p><label class="s" style="display:block;margin-top:10px"><span id="publish-price-label">Prix (si vente)</span><input id="publish-price" type="number" min="0" step="0.01" inputmode="decimal" placeholder="Ex. 25"></label><div id="auction-fields" hidden><label class="s" style="display:block;margin-top:10px">Pas minimum entre deux enchères (€)<input id="publish-bid-step" type="number" min="0.01" step="0.01" value="1"></label><label class="s" style="display:block;margin-top:10px">Durée<select id="publish-auction-days"><option value="1">1 jour</option><option value="3" selected>3 jours</option><option value="7">7 jours</option></select></label><p class="s" style="margin-top:8px">Les enchères et montants sont simulés localement, sans paiement réel.</p></div><label class="s" style="display:block;margin-top:10px">Ville ou secteur<input id="publish-location" maxlength="80" placeholder="Ex. Paris 11e"></label><label class="s" style="display:block;margin-top:10px">Code postal (facultatif)<input id="publish-postal-code" inputmode="numeric" maxlength="5" placeholder="Ex. 75011"></label><label class="s" style="display:block;margin-top:10px">Photos (8 maximum, enregistrées localement)<input type="file" accept="image/*" multiple onchange="addPhotos(this.files)"></label><div class="photos" id="photo-previews">'+photoPreviews()+'</div></div><button class="p" style="margin-top:12px" onclick="publierAnnonce()">Publier l’annonce</button>'}
function publierAnnonce(){if(S.pendingPhotos){toast("Attends la fin de la préparation des photos.");return}var title=$("publish-name").value.trim(),game=$("publish-game").value,type=$("publish-type").value,condition=$("publish-condition").value,price=$("publish-price").value.trim(),location=$("publish-location").value.trim(),postalCode=$("publish-postal-code").value.trim(),centeringGrade=$("publish-centering").value||null,defects=CARD_DEFECTS.filter(function(defect){var input=$("publish-defect-"+defect.id);return input&&input.checked}).map(function(defect){return defect.id}),amount=Number(price.replace(",",".")),auction=type=="Enchère",step=auction?Number($("publish-bid-step").value):1,days=auction?Number($("publish-auction-days").value):0;if(!title||!game){toast("Indique le nom de la carte et son jeu.");return}if(postalCode&&!/^\d{5}$/.test(postalCode)){toast("Le code postal doit contenir 5 chiffres.");$("publish-postal-code").focus();return}if(type!="Échange"&&(!price||!Number.isFinite(amount)||amount<=0)){toast(auction?"Saisis un prix de départ valide.":"Saisis un prix valide pour la vente.");return}if(centeringGrade&&CENTERING_QUALITIES.indexOf(centeringGrade)<0){toast("Choisis un niveau de centrage valide.");$("publish-centering").focus();return}if(auction&&(!Number.isFinite(step)||step<=0||[1,3,7].indexOf(days)<0)){toast("Vérifie le pas minimum et la durée de l’enchère.");return}var id=L.reduce(function(max,l){return Math.max(max,l.id)},0)+1,listing={id:id,t:title,g:game,e:condition,p:auction?"Enchère":type=="Vente"?money(amount):"Échange",v:location||"Localisation à définir",cp:postalCode,d:"0 km",u:"toi",s:"—",n:0,m:0,x:"Nouvelle annonce.",photos:S.photos.slice()};if(defects.length)listing.defects=defects;if(centeringGrade!==null)listing.centeringGrade=centeringGrade;if(type=="Échange")listing.ex=1;if(auction){listing.auction=true;listing.startPrice=amount;listing.currentBid=amount;listing.bidStep=step;listing.endsAt=Date.now()+days*86400000;listing.bids=[];listing.highestBidder=""}L.unshift(listing);G=Array.from(new Set(L.map(function(l){return l.g})));var myListing={t:title,p:listing.p,e:condition,v:listing.v,id:id,photos:listing.photos,st:"En ligne",auction:listing.auction,startPrice:listing.startPrice,currentBid:listing.currentBid,bidStep:listing.bidStep,endsAt:listing.endsAt,bids:listing.bids};if(defects.length)myListing.defects=defects.slice();if(centeringGrade!==null)myListing.centeringGrade=centeringGrade;MY.unshift(myListing);S.photos=[];saveDemo();go("detail",{id:id});toast(auction?"Enchère publiée et enregistrée dans ce navigateur.":"Annonce publiée et enregistrée dans ce navigateur.")}
function settings(){return '<h2>Réglages</h2><p class="s">Personnalise l’affichage de TCG Safe. Tes préférences sont enregistrées sur cet appareil.</p><div class="card"><div class="row"><div><h3>Apparence</h3><p class="s">Choisis le thème qui te convient.</p></div><span class="b">Affichage</span></div><label class="s" style="display:block;margin-top:12px">Thème de l’application<select id="theme-preference" onchange="setThemePreference(this.value)"><option value="system" '+(THEME_PREFERENCE=="system"?"selected":"")+'>Suivre le thème de l’appareil</option><option value="light" '+(THEME_PREFERENCE=="light"?"selected":"")+'>Clair</option><option value="dark" '+(THEME_PREFERENCE=="dark"?"selected":"")+'>Nuit</option></select></label><p class="s" style="margin-top:7px">Le mode nuit réduit la luminosité de l’interface.</p></div><div class="card"><h3>Accessibilité</h3><p class="s" style="margin-top:4px">Ajuste les animations selon tes préférences.</p><label class="setting-row"><span><b>Réduire les animations</b><span class="s">Désactive les mouvements décoratifs de l’interface.</span></span><input id="motion-preference" type="checkbox" '+(MOTION_REDUCED?"checked":"")+' onchange="setReducedMotion()"></label></div><div class="card"><h3>Profil et données</h3><p class="s" style="margin-top:4px">Le profil, les annonces et les préférences restent stockés dans ce navigateur.</p><div class="row" style="margin-top:10px"><button onclick="go(\'profil\',{pu:\'toi\',pt:\'Annonces\'})">Mon profil</button><button onclick="go(\'notifications\')">Notifications</button></div></div>'}
function nav(){var a=S.sc,me=(S.pu||"toi")=="toi",auction=a=="home"&&S.ft=="Enchères",feed=a=="home"&&!auction,unread=notificationUnreadCount();return `<nav class="nav"><button class="${feed?"on":""}" onclick="setFeed('Fil')">Fil</button><button class="${auction?"on":""}" onclick="setFeed('Enchères')">Enchères</button><button class="${a=="publier"?"on":""}" onclick="go('publier')">Publier</button><button class="${a=="messages"||a=="chat"?"on":""}" aria-label="Messages" title="Messages" onclick="go('messages')">Chat</button><button class="${a=="notifications"?"on":""}" aria-label="Notifications${unread?", "+unread+" non lues":""}" onclick="go('notifications')">Notifs${unread?'<span class="nav-badge">'+unread+'</span>':""}</button><button class="${a=="profil"&&me?"on":""}" onclick="go('profil',{pu:'toi',pt:'Annonces'})">Profil</button><button class="${a=="settings"?"on":""}" onclick="go('settings')">Réglages</button></nav>`}
