if(S.sc=="suivi"){var meetingChat=$("meeting-chat-messages");if(meetingChat)meetingChat.scrollTop=meetingChat.scrollHeight;if(MEETING&&MEETING.status=="en route"){updateDelayedLocationUI();if(!LOCATION_TIMER&&Number.isFinite(MEETING.departedAt)&&Date.now()-MEETING.departedAt<LOCATION_DELAY_MS)LOCATION_TIMER=setInterval(updateDelayedLocationUI,1000)}}
